/** Get MLA profile by constituency number */
export function getUPMLAProfile(acNo: number): MLAProfile | undefined {
  return UP_MLA_PROFILES.find((p) => p.acNo === acNo);
}

/** Get all MLA profiles */
export function getAllUPMLAs(): MLAProfile[] {
  return UP_MLA_PROFILES;
}
